corrected_code:
@router.get("/users/activity-summary")
def get_user_activity(
    target_user_id: int = Query(...),
    token: TokenPayload = Security(verify_token_scopes, scopes=["profile:view"]),
    db: Session = Depends(get_db)
):
    if target_user_id != token.user_id and not token.is_admin:
        raise HTTPException(status_code=403, detail="Cannot view activity logs of other users")
    activity = db.query(UserActivityLog).filter(UserActivityLog.user_id == target_user_id).all()
    return {"user_id": target_user_id, "logs": activity}
